private async Task<ResultadoConversacion?> AvanzarAsync(Turnos estado, CancellationToken cancellationToken)
{
    var solicitud = Solicitar(estado);
    var respuesta = await _clienteLlm.CompletarAsync(solicitud, cancellationToken);
    _uso.Sumar(respuesta.Uso);
    estado.Invocaciones += respuesta.Llamadas.Count;
    var terminal = ContextoTruncado(solicitud, respuesta.Uso) ?? Terminal(estado, respuesta);
    return terminal ?? await EjecutarHerramientasAsync(estado, respuesta, cancellationToken);
}

private ResultadoConversacion? ContextoTruncado(SolicitudLlm solicitud, UsoTokens uso)
{
    if (!_configuracion.Ajustes.ContextoLocal || uso.Entrada <= 0)
    {
        return null;
    }

    var estimados = TokensEstimados(solicitud);
    var minimo = (int)Math.Ceiling(ProporcionMinimaDelContexto * estimados);
    if (uso.Entrada >= minimo)
    {
        return null;
    }

    _configuracion.Advertir($"Contexto del proveedor local truncado: estimación de {estimados} tokens y prompt_tokens reportados {uso.Entrada}.");
    return new ResultadoConversacion(EstadoConversacion.ContextoTruncado, null);
}

