import fs from 'node:fs';
const dir = process.argv[2];
const salida = process.argv[3];
const hex = (n) => n.toString(16).toUpperCase().padStart(4, '0');
const lineas = fs.readFileSync(`${dir}/UnicodeData.txt`, 'utf8').split('\n').filter((l) => l.trim());
const gc = new Map();
const decomp = new Map();
for (const l of lineas) {
  const c = l.split(';');
  const cp = parseInt(c[0], 16);
  gc.set(cp, c[2]);
  if (c[5]) decomp.set(cp, c[5].replace(/^<[^>]*>\s*/, '').split(' ').map((h) => parseInt(h, 16)));
}
const esSust = (cp) => cp >= 0xd800 && cp <= 0xdfff;
const completa = (cp) => (decomp.has(cp) ? decomp.get(cp).flatMap(completa) : [cp]);
const filas = { desc: [], mn: [], conf: [], trazo: [], nd: [], cf: [] };
for (const cp of [...gc.keys()].sort((a, b) => a - b)) {
  const cat = gc.get(cp);
  if (esSust(cp)) continue;
  if (cat === 'Mn') filas.mn.push([hex(cp), '']);
  if (cat === 'Cf') filas.cf.push([hex(cp), '']);
  if (cat === 'Nd' && cp > 0x7f) filas.nd.push([hex(cp), hex(0x30 + Number(String.fromCodePoint(cp).match(/\p{Nd}/u) ? digito(cp) : 0))]);
  if (decomp.has(cp) && cat !== 'Mn') {
    const destino = completa(cp).filter((d) => gc.get(d) !== 'Mn');
    if (destino.length > 0 && destino.every((d) => gc.get(d) !== 'Cf')) filas.desc.push([hex(cp), destino.map(hex).join(' ')]);
  }
}
function digito(cp) {
  let base = cp;
  while (gc.get(base - 1) === 'Nd' && base - 1 >= 0 && (cp - (base - 1)) < 10) base--;
  return cp - base;
}
const trazo = { 0x166: 'T', 0x167: 't', 0x110: 'D', 0x111: 'd', 0x141: 'L', 0x142: 'l', 0xd8: 'O', 0xf8: 'o' };
for (const cp of Object.keys(trazo).map(Number).sort((a, b) => a - b)) filas.trazo.push([hex(cp), hex(trazo[cp].charCodeAt(0))]);
const conf = new Map();
for (const l of fs.readFileSync(`${dir}/confusables.txt`, 'utf8').split('\n')) {
  const t = l.replace(/^﻿/, '');
  if (!t.trim() || t.startsWith('#')) continue;
  const p = t.split(';').map((x) => x.trim());
  const origen = p[0].split(' ').filter(Boolean);
  const destino = p[1].split(' ').filter(Boolean);
  if (origen.length !== 1 || destino.length !== 1) continue;
  const o = parseInt(origen[0], 16);
  const d = parseInt(destino[0], 16);
  if (o <= 0xff || esSust(o)) continue;
  if (!/^[A-Za-z0-9]$/.test(String.fromCodePoint(d))) continue;
  conf.set(o, d);
}
for (const o of [...conf.keys()].sort((a, b) => a - b)) filas.conf.push([hex(o), hex(conf.get(o))]);
const salidaLineas = ['#UnicodeData\t16.0.0', '#confusables\t16.0.0'];
for (const tipo of ['desc', 'mn', 'conf', 'trazo', 'nd', 'cf']) for (const [o, d] of filas[tipo]) salidaLineas.push(`${tipo}\t${o}\t${d}`);
fs.writeFileSync(salida, salidaLineas.join('\n') + '\n');
console.log(Object.fromEntries(Object.entries(filas).map(([k, v]) => [k, v.length])));

