const dir = process.argv[2];
const salida = process.argv[3];
const hex = (n) => n.toString(16).toUpperCase().padStart(4, '0');
const lineas = fs.readFileSync(`${dir}/UnicodeData.txt`, 'utf8').split('\n').filter((l) => l.trim());
const gc = new Map();
const decomp = new Map();
for (const l of lineas) {
  const c = l.split(';');
  const cp = parseInt(c[0], 16);
  gc.set(cp, c[2]);
  if (c[5]) decomp.set(cp, c[5].replace(/^<[^>]*>\s*/, '').split(' ').map((h) => parseInt(h, 16)));
