    [Trait("ESC", "ESC-185")]
    [Trait("RF", "SEG-10g")]
    public async Task ESC_185_Una_definitiva_de_Estadistica_en_el_formato_de_un_modelo_se_verifica_y_falla_cerrada(string caso, string texto)
