    {
        var previas = palabras.Skip(cantidad).Select(palabra => (palabra.Inicio, Valor: NormalizadorTexto.Normalizar(palabra.Valor))).ToList();
        var documentoDe = previas.Count > 1 && previas[0].Valor == "de" && previas[1].Valor == "documento";
        var prefijo = previas.Count > 0 && PrefijosDelNombre.Contains(previas[0].Valor);
        return documentoDe ? previas[1].Inicio : prefijo ? previas[0].Inicio : palabras[cantidad - 1].Inicio;
