        Regex.IsMatch(plegado, $@"(?<![\p{{L}}\p{{N}}.]){Regex.Escape(termino)}(?![\p{{L}}\p{{N}}])", RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(TiempoLimiteRegex.Milisegundos));

