        await escenario.PreguntarAsync(new Usuario(Rol.Coordinador, coordinador), $"¿Cómo va {estudianteId} en asistencia?");

        Assert.Contains(linea, Lineas(ContenidoDeHerramienta(escenario.Llm, 1)));
    }

