        var nombre = resultado.Asignatura.Nombre;
        var clases = resultado.Asignatura.Asistencia.ClasesProgramadas;
        var maximo = resultado.FaltasPermitidas;
        if (resultado.Asignatura.Asistencia.Inasistencias is not { } faltas)
        {
            var revision = terceraPersona ? "Solicite la revisión al coordinador del programa" : "Solicita la revisión a tu coordinador";
            return $"{nombre}: sin registro de inasistencias en {clases} clases programadas (máximo sin perder: {maximo}). {revision} ({Textos.SeccionAsistenciaSinRegistro}).";
        }

        return resultado.Estado == EstadoAsignatura.PerdidaPorInasistencia
            ? $"{nombre}: faltas {faltas} de {clases} clases programadas (faltas restantes: 0; máximo sin perder: {maximo}). Perdida por inasistencia: {(terceraPersona ? "superó" : "superaste")} {maximo} inasistencias."
            : $"{nombre}: faltas {faltas} de {clases} clases programadas (faltas restantes: {Math.Max(maximo - faltas, 0)}; máximo sin perder: {maximo}). Si {(terceraPersona ? "supera" : "superas")} {maximo} inasistencias {(terceraPersona ? "pierde" : "pierdes")} la asignatura por inasistencia.";
    }
}

